body.usercss:

textarea.remarkTA {
    width: calc(100% - 10px);
    height: calc(100% - 10px);
    resize: none;
    border: none;
    padding: 5px;
}

userscript.function:

$share.items = {};
$share.items.tabbarObj1 = new SepoaDhtmlXTabBar(formObj.getContainer('TAP_AREA1'));
$share.items.tabbarObj1.addTab('contract', Sepoa.cache.text.get('CT_205_A.CONTRACT'));
$share.items.vaultContract = $share.items.tabbarObj1.tabs('contract').attachVault({
    mode : '',
    type : 'CONT_C',
    service : 'sepoa.svc.ct.CT_205',
    select : 'doFileList',
    upload : 'doFileUpload',
    delete : 'doFileDelete'
});
$share.items.tabbarObj1.addTab('attach', Sepoa.cache.text.get('CT_205_A.ATTACH'));
$share.items.vaultAttach = $share.items.tabbarObj1.tabs('attach').attachVault({
    mode : '',
    type : 'CONT_A',
    service : 'sepoa.svc.ct.CT_205',
    select : 'doFileList',
    upload : 'doFileUpload',
    delete : 'doFileDelete'
});

for(let item of Object.values($share.items)) {
    if(item.constructor.name == 'SepoaDhtmlXVaultObject') {
        initVault(item);
    }
}

if (Sepoa.request.DOC_TYPE == 'MANUAL') {
    formObj.hideItem('TAP_AREA2');
} else {
    $share.items.tabbarObj2 = new SepoaDhtmlXTabBar(formObj.getContainer('TAP_AREA2'));
    $share.items.tabbarObj2.addTab('remark', Sepoa.cache.text.get('CT_205_A.REMARK'));
    $share.items.remark = $('<textarea rows="10" class="remarkTA"></textarea>')[0];
    $share.items.tabbarObj2.tabs('remark').attachObject($share.items.remark);
}


callFunction('p', 'childScreenReady', [{
    name:'BASIC',
    id: $sObject.aliasCode,
    fn:{
        doOpenDocument:doOpenDocument,
        doClear:doClear,
        doValidate:doValidate,
        doValidateAttach:doValidateAttach,
        setViewMode:setViewMode,
        hideVaultContract:hideVaultContract
    }
}])


const taskList = [];
vaultObj.attachEvent('onUploadComplete', function(info) {
    if(taskList.length > 0) {
        for(let task of taskList) {
            task.item.setAttachKey(task.key);
        }

        taskList.length = 0;
    }
});

vaultObj.attachEvent('onFileRemove', function(info) {
    const data = vaultObj.getData();
    if(data.length === 0) {
        callFunction('p', 'hideTemplateFormItem', [false]);
    }
});

vaultObj.attachEvent('onUploadFile', function(info) {
    if($share.config?.data) {
        const data = $share.config.data;

        if(info.serviceObj) {
            const currentObj = {
                SIGN_ORDER : data.SIGN_ORDER,
                CONT_METHOD : data.CONT_METHOD ?? ''
            };

            sUtils.object.extend(true,
                data,
                info.serviceObj,
                currentObj
            );

            if(!sUtils.string.isBlank(data.CONT_NO) && !sUtils.string.isBlank(data.CONT_GL_SEQ)) {
                for(let item of Object.values($share.items)) {
                    if(item.constructor.name == 'SepoaDhtmlXVaultObject') {
                        const currentKey = item.getAttachKey();
                        const newKey = [data.CONT_NO, data.CONT_GL_SEQ, item.conf.type].join('#');
                        if(currentKey != newKey) {
                            taskList.push({
                                item : item,
                                key : newKey
                            });
                        }
                    }
                }
            }
        }

        if(vaultObj.conf.type == 'CONT_C') {
            const data = vaultObj.getData();
            if(data.length > 0) {
                callFunction('p', 'hideTemplateFormItem', [true]);
            }
        }
    }
});

vaultObj.setDragNDrop(false);


if($share.items.tabbarObj1.tabs('contract').isVisible()) {
    const cnt = $share.items.vaultContract.getData().length;

    return cnt > 0 ? true : false;
} else {
    return true;
}


if(flag){
    formObj.setViewMode(true);
    $share.items.vaultContract.changeMode("VI");
    $share.items.vaultAttach.changeMode("VI");
    $share.items.remark.readOnly = true;
}else{
    formObj.setViewMode(false);
    $share.items.vaultContract.changeMode("");
    $share.items.vaultAttach.changeMode("");
    $share.items.remark.readOnly = false;
    var config = $share.config
}


$share.config = config;

//default date
if(!config.data) {
    config.data = {};
}
if(!config.data.CONT_DATE) {
    config.data.CONT_DATE = sUtils.date.getToday();
}
if(!config.data.CONT_FROM) {
    config.data.CONT_FROM = sUtils.date.getToday();
}

formObj.dataMapper(structuredClone(config.data), "JSON");

if(config.data.CONT_TO != '' && config.data.EXPIRED_ALARM_DATE == ''){
    if(sUtils.workflow.check('CT1662605670342')){//계약만료알림일 자동계산
        var cont_to = config.data.CONT_TO;
        var month = sUtils.workflow.getOptions('CT1662605670342');
        if(month == undefined) {
            month =2;
        } 
           var alarm_date = calDate(cont_to,month);
           formObj.setValue('EXPIRED_ALARM_DATE',alarm_date);
       }
}

if($share.config.document) {
    if($share.config.document.SMR_NUMBER) {     // 날인 완료건에 대한 계약 문서일 경우 계약 문서 파일 첨부를 제한한다.
        $share.items.tabbarObj1.tabs('contract').hide();
    }

    if($share.config.document.CONT_NO && $share.config.document.CONT_GL_SEQ) {
        const docNo = [
            $share.config.document.CONT_NO,
            $share.config.document.CONT_GL_SEQ
        ].join('#');

        //vault - contract
        const extraData = getDocumentExtra($share.config.document.CONT_NO, $share.config.document.CONT_GL_SEQ);
        $share.config.data.EXTRA = extraData.EXTRA;
        for(let entry of Object.entries($share.config.data.EXTRA)) {
            const [key, value] = entry;
            formObj.setValue(key.replace('EX_', ''), value);
        }

        const hasSourceNo = !sUtils.string.isBlank(extraData.EXTRA?.EX_SOURCE_NO);
        const hasFormNo = !sUtils.string.isBlank($share.config.data.CONT_FORM_NO);
        if(hasSourceNo) {
            hideVaultContract(true);

            if(!hasFormNo) {
                callFunction('p', 'hideTemplateFormItem', [true]);
            }
        } else {
            if(hasFormNo) {
                hideVaultContract(true);
            } else {
                $share.items.vaultContract.setAttachKey(docNo + '#CONT_C');
            }
        }

        //vault - attach
        $share.items.vaultAttach.setAttachKey(docNo + '#CONT_A');
    }
}

//remark
if($share.items.remark){
    $share.items.remark.value = config.data.REMARK
}
if (!config.data.CONT_AMT || config.data.CONT_AMT == '') {
    onChange('SUPPLY_AMT', config.data.SUPPLY_AMT)
}


if(!formObj.validate()){
    Alert(Sepoa.cache.text.get('CT_205.MSG6'));//입력되지않은 필수값이 존재합니다.
    return false;
}

return true;


if(id =='SUPPLY_AMT' || id == 'TAX_AMT' || id == 'CONT_AMT'){
    const check =/[^0-9]/g;
    if (check.test(nValue)){
        formObj.setValue(id,nValue.replace(check,''));
        return false;
    }
}

return true;


if(name == 'CONT_TO') {
    $share.config.data.CONT_TO = sUtils.date.toString(value).replace(/\D/g, '')
} else if(name == 'CONT_FROM') {
    $share.config.data.CONT_FROM = sUtils.date.toString(value).replace(/\D/g, '')
} else {
    if(['SUPPLY_AMT'].includes(name)) {
    	const taxAmt = parseFloat(formObj.getValue('SUPPLY_AMT') || 0) * 0.1;
    	formObj.setValue('TAX_AMT', taxAmt.toString());
        const contAmt = parseFloat(formObj.getValue('SUPPLY_AMT') || 0) + parseFloat(formObj.getValue('TAX_AMT') || 0);
        formObj.setValue('CONT_AMT', contAmt.toString());
    }

    $.extend(true, $share.config.data, formObj.getFormData(true));
}

callFunction('p', 'onChangeData', ['BASIC']);


var year = Number(date.substring(0,4));
var month = Number(date.substring(4,6));
var day = Number(date.substring(6,8));

var changeMonth = month - clDateMonth;
if( changeMonth <= 0){
    changeMonth = 12 + changeMonth
    year = year - (Math.floor(clDateMonth/12)+1)
}else if (changeMonth > 12){
    changeMonth = changeMonth - 12
    year = year + (Math.floor(clDateMonth/12)+1)
}

var lastDate = new Date(year,changeMonth,0).getDate();
if(lastDate < day){
    day = lastDate;
}

if (changeMonth > 12){
    changeMonth = changeMonth - 12
    year = year + 1
}

if(changeMonth < 10){
    changeMonth = '0'+changeMonth;
}
if(day < 10){
    day = '0'+day;
}

return String(year)+String(changeMonth)+String(day);


const targetVault = $share.items.vaultContract;
const targetTab = $share.items.tabbarObj1.tabs('contract');
if(flag) {
   targetVault.clear();
   targetTab.hide();
} else {
    targetTab.show();
    targetTab.setActive();

    const attachKey = targetVault.getAttachKey();
    if(attachKey) {
        targetVault.setAttachKey(attachKey);
    }
}


const config = {
    url: window.CONTEXT_NAME + '/SepoaActionController.sux',
    async : false,
}

const params = {
    module: "contract",
    action: "doDocumentExtra",
    CONT_NO: contNo,
    CONT_GL_SEQ: contGlSeq
};

const so = sUtils.multipart.send(config, params);

return {
    EXTRA : so.result[0],
    SIGNER_LIST : so.result[1]
};
